<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/src/SepayCardProtocol.php';
function check(bool $ok,string $why):void{if(!$ok)throw new RuntimeException($why);}
function invalid(callable $fn,string $why):void{try{$fn();}catch(InvalidArgumentException){return;}throw new RuntimeException($why);}
$fixture=json_decode(file_get_contents(__DIR__.'/fixtures/sepay-card-node.json'),true,512,JSON_THROW_ON_ERROR);
foreach($fixture['signatures'] as $case)check(SepayCardProtocol::sign($case['fields'],$fixture['secret'])===$case['signature'],'Source signature bytes/order/Unicode');
foreach($fixture['money'] as $case){if($case['amount']===null)invalid(fn()=>SepayCardProtocol::amount($case['value']),'Reject source amount '.$case['value']);else check(SepayCardProtocol::amount($case['value'])===$case['amount'],'Source amount');}
$f=$fixture['signatures'][0]['fields'];
foreach(['TEST'=>'https://pay-sandbox.sepay.vn/v1/checkout/init','LIVE'=>'https://pay.sepay.vn/v1/checkout/init'] as $mode=>$action){$form=SepayCardProtocol::form($mode,$f['merchant'],$fixture['secret'],$f['order_invoice_number'],'JC1234567890',15000000000,'https://merchant.example.test/');check($form===['action'=>$action,'fields'=>$f+['signature'=>$fixture['signatures'][0]['signature']]],'Exact form contract '.$mode);check(!str_contains(json_encode($form),$fixture['secret']),'Form never exposes secret');}
foreach(['http://merchant.test','https://user:secret@merchant.test','https://merchant.test/subdir','https://merchant.test?x=1','https://merchant.test#x','javascript:alert(1)'] as $base)invalid(fn()=>SepayCardProtocol::form('LIVE','M',$fixture['secret'],$f['order_invoice_number'],'JM1234567890',100,$base),'Reject unsafe return origin');
invalid(fn()=>SepayCardProtocol::form('PROD','M','secret',$f['order_invoice_number'],'JM1234567890',100,'https://merchant.test'),'Bad mode');
invalid(fn()=>SepayCardProtocol::sign(['order_amount'=>100],'secret'),'No implicit signing coercion');
$body=['timestamp'=>1794906000,'notification_type'=>'ORDER_PAID','order'=>['id'=>'ORDER_1','order_status'=>'CAPTURED','order_currency'=>'VND','order_amount'=>'100.00','order_invoice_number'=>$f['order_invoice_number']],'transaction'=>['id'=>'TX-1','payment_method'=>'CARD','transaction_type'=>'PAYMENT','transaction_status'=>'APPROVED','transaction_amount'=>100,'transaction_currency'=>'VND']];
$expected=['invoice'=>$f['order_invoice_number'],'external'=>'TX-1:ORDER_PAID','amount'=>100,'fingerprint'=>$fixture['fingerprint'],'reason'=>''];
check(SepayCardProtocol::notification($body)===$expected,'Exact source normalized fingerprint');
$private=$body;$private['customer']=['name'=>'PRIVATE CUSTOMER','email'=>'PRIVATE EMAIL'];$private['card']=['number'=>'PRIVATE CARD','cvv'=>'PRIVATE CVV'];$private['order']['extra']='PRIVATE ORDER';$private['transaction']['extra']='PRIVATE TRANSACTION';
check(SepayCardProtocol::notification($private)===$expected&&!str_contains(json_encode(SepayCardProtocol::notification($private)),'PRIVATE'),'Discard all non-settlement fields');
foreach(['100','0100','100.0','100.00',100,100.0] as $amount){$p=$body;$p['order']['order_amount']=$p['transaction']['transaction_amount']=$amount;check(SepayCardProtocol::notification($p)===$expected,'Equivalent source money same fingerprint');}
foreach([['notification_type','TRANSACTION_VOID'],['order.order_status','PENDING'],['transaction.transaction_status','DECLINED'],['transaction.transaction_type','REFUND'],['transaction.payment_method','BANK_TRANSFER'],['order.order_currency','USD'],['transaction.transaction_currency','USD'],['order.order_amount','101']] as [$key,$value]){$p=$body;$parts=explode('.',$key);if(count($parts)===1)$p[$key]=$value;else $p[$parts[0]][$parts[1]]=$value;$result=SepayCardProtocol::notification($p);check($result['reason']!==''&&$result['fingerprint']!==$expected['fingerprint'],'Nonpaid/mismatch retained for REVIEW');if($key==='notification_type')check($result['external']==='TX-1:TRANSACTION_VOID','Paid and void have different event identifiers');}
invalid(fn()=>SepayCardProtocol::notification([]),'Empty root');
foreach([null,['timestamp'=>'1794906000'],['timestamp'=>0],['notification_type'=>'OTHER'],['order'=>null],['transaction'=>[]]] as $patch){$p=$patch===null?null:array_replace($body,$patch);invalid(fn()=>SepayCardProtocol::notification($p),'Reject malformed notification');}
foreach(['order'=>['id'=>['','bad id',str_repeat('a',101)],'order_invoice_number'=>['JMP'.str_repeat('a',24),'JM1234567890',null],'order_amount'=>[null,true,0,-1,1.5,'1.01','1e2',15000000001],'order_currency'=>[null,100,str_repeat('x',11)]],'transaction'=>['id'=>['bad:id',null],'transaction_amount'=>[null,[],false,INF,NAN],'transaction_status'=>[str_repeat('x',41)],'payment_method'=>[[]]]] as $kind=>$keys)foreach($keys as $key=>$values)foreach($values as $value){$p=$body;$p[$kind][$key]=$value;invalid(fn()=>SepayCardProtocol::notification($p),'Reject malformed '.$key);}
$p=$body;$p['timestamp']++;check(SepayCardProtocol::notification($p)===$expected,'Delivery timestamp excluded from replay fingerprint');
echo "PASS: original Node card signatures, exact checkout forms, VND boundaries, normalized IPN fingerprints, REVIEW reasons and removal of cardholder data.\n";
